import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Usage } from '../types'
import { applyTimerFiles, formatLeft, isCounting, isExit, takeSeen, timerArgs, timerViewAt, TIMER_COMMAND } from './timer'

// The game's HUD: toxicity climbs as the session drinks context, stamina
// drains fast and comes back (the 5-hour window), vitality drains slowly (the
// 7-day window). Running agents are the engine's own panel below the prompt
// (subagentStatusLine), not this band.
const usage = atom({ plugin: 'witcher', key: 'usage' } as const, {
  ctx: null,
  fiveHour: null,
  fiveHourReset: null,
  sevenDay: null,
} as Usage)

// A session is meant to be handed off to a fresh one at 30 % of context, so the
// toxicity bar marks that line the way the game marks the overdose threshold.
// Where to hand off is a habit, not a law, so `toxicityThreshold` moves it.
const DEFAULT_TOXICITY_THRESHOLD = 30
// Past the mark by this much the handoff is overdue, and the bar turns red.
const TOXICITY_OVERDUE_BY = 10

function bar(percent: number, width: number): string {
  const filled = Math.round((Math.min(100, Math.max(0, percent)) / 100) * width)
  return '▰'.repeat(filled) + '▱'.repeat(width - filled)
}

// Toxicity carries the threshold mark inside the bar, like the game's line.
function toxicityBar(percent: number, threshold: number, width: number): string {
  const cells = bar(percent, width).split('')
  const mark = Math.round((threshold / 100) * width)
  if (mark < width) cells[mark] = cells[mark] === '▰' ? '▮' : '│'
  return cells.join('')
}

function hhmm(iso: string | null): string {
  if (!iso) return ''
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return ''
  const h = String(d.getHours()).padStart(2, '0')
  const m = String(d.getMinutes()).padStart(2, '0')
  return `${h}:${m}`
}

type Dollar = EngineInterface

async function refreshUsage($: Dollar) {
  const u = await $.session.usage()
  const limit = (kind: string) => u.rateLimits.find(r => r.kind === kind)
  const next: Usage = {
    ctx: u.context.percent ?? (u.context.tokens ? Math.round((u.context.tokens / u.context.window) * 100) : null),
    fiveHour: limit('five_hour')?.percentUsed ?? null,
    fiveHourReset: limit('five_hour')?.resetsAt ?? null,
    sevenDay: limit('seven_day')?.percentUsed ?? null,
  }
  await update($, usage, () => next)
}

// Several persona plugins can sit side by side; personas/active names the one
// on duty and the others keep quiet. Undefined when the marker can't be read:
// at session start that means nobody has chosen yet, so a lone plugin works
// straight after install; mid-session it is a switch in progress.
async function isOnDuty($: Dollar): Promise<boolean | undefined> {
  try {
    const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${await $.env.get('HOME')}/.claude`
    const active = String(await $.fs.read(`${dir}/personas/active`)).trim()
    return active === 'witcher'
  } catch {
    return undefined
  }
}

// Unknown until first asked: a default either way would flash the wrong band.
let onDuty: boolean | undefined
let stopWatching: (() => void) | undefined

// The switch can come from another plugin's command or another session, and
// neither can reach this module, so it polls the marker and redraws on change.
const DUTY_POLL_MS = 3000

// The break timer's state files, shared by every session and both personas
async function timerDir($: Dollar): Promise<string | null> {
  try {
    const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${await $.env.get('HOME')}/.claude`
    return `${dir}/persona-timer`
  } catch {
    return null
  }
}

async function readOrNull($: Dollar, path: string): Promise<string | null> {
  try {
    return String(await $.fs.read(path))
  } catch {
    return null
  }
}

async function refreshTimer($: Dollar): Promise<boolean> {
  const dir = await timerDir($)
  if (!dir) return false
  return applyTimerFiles(
    await readOrNull($, `${dir}/timer.json`),
    await readOrNull($, `${dir}/rang.json`),
    await readOrNull($, `${dir}/seen`),
  )
}

async function runTimer($: Dollar, args: string): Promise<string> {
  const r = await $.process
    .run(['bash', `${$.plugin.root}/scripts/timer.sh`, ...timerArgs(args)])
    .catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
  return (r.exitCode === 0 ? r.stdout : r.stderr).trim()
}

async function recheckDuty($: Dollar) {
  const timerChanged = await refreshTimer($)
  const now = await isOnDuty($)
  if (now !== undefined && now !== onDuty) {
    onDuty = now
    $.ui.invalidate('ui.render')
  } else if (timerChanged && onDuty) {
    $.ui.invalidate('ui.render')
  }
}

// The engine samples the spinner word from the verbs it read at session start,
// so a persona put on mid-session would keep the previous one's words; on duty,
// this plugin swaps in its own.
let verbs: readonly string[] = []

async function loadVerbs($: Dollar) {
  try {
    verbs = JSON.parse(String(await $.fs.read(`${$.plugin.root}/persona/verbs.json`))).verbs ?? []
  } catch {
    verbs = []
  }
}

// The engine samples its word once per turn, so the verb starts from it (or
// from a hash of a word that isn't this persona's) and moves `step` verbs on,
// one step per `spinnerSeconds`: a long turn doesn't sit on one line, and
// redraws within a step keep the same verb.
export function ownVerb(sampled: string, own: readonly string[], step = 0): string {
  if (own.length === 0) return sampled
  let start = own.indexOf(sampled)
  if (start < 0) {
    let h = 0
    for (const ch of sampled) h = (h * 31 + ch.charCodeAt(0)) >>> 0
    start = h % own.length
  }
  return own[(start + step) % own.length]!
}

// When each sampled word was first drawn: the main spinner and each agent's
// carry their own word, so each counts its steps from its own start.
const firstSeen = new Map<string, number>()

async function stepsSince($: Dollar, word: string, stepMs: number): Promise<number> {
  const now = await $.clock.now()
  if (firstSeen.size > 64) firstSeen.clear()
  const start = firstSeen.get(word) ?? now
  firstSeen.set(word, start)
  return Math.floor((now - start) / stepMs)
}

// Redraws often enough that a step lands within a few seconds of falling due
const SPINNER_TICK_MS = 5000
// The break countdown shows seconds
const TIMER_TICK_MS = 1000

// Wearing the persona rewrites the person's own settings, so it is a command
// they run, never a side effect of installing the plugin. wear.sh owns the
// list of themes and says what changed and where it shows up.
async function wear($: Dollar, args: string): Promise<string> {
  const arg = args.trim()
  const argv = ['bash', `${$.plugin.root}/scripts/wear.sh`, ...(arg === 'off' ? ['off'] : ['on', ...(arg ? [arg] : [])])]
  const r = await $.process.run(argv).catch((err: unknown) => ({ exitCode: -1, stdout: '', stderr: String(err) }))
  if (r.exitCode !== 0) return `Failed: ${r.stderr.trim()}`
  return r.stdout.trim()
}

export const register: Register = (on, options) => {
  const stepMs = Math.max(10, Number(options.spinnerSeconds) || 30) * 1000
  // Same bounds as toxicityThreshold in plugin.json; the clamp covers a value the host saved unchecked
  const threshold = Math.min(90, Math.max(5, Number(options.toxicityThreshold) || DEFAULT_TOXICITY_THRESHOLD))

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'witcher',
      description: 'Put on The Witcher 3 persona: theme, spinner, status line, terminal profile',
      argumentHint: '[corvo-bianco | kaer-morhen | off]',
    })
    // Both persona plugins carry /timer and the first to start owns it; the
    // other's refusal must not cost it the rest of its start
    await $.command.register(TIMER_COMMAND).catch(() => undefined)
    // The persona on duty when the timer rings may not be the plugin that set
    // it, so each plugin says where its phrases and clip live
    const dir = await timerDir($)
    if (dir) await $.fs.write(`${dir}/roots/witcher`, $.plugin.root).catch(() => undefined)
    await refreshTimer($)
    onDuty = (await isOnDuty($)) ?? true
    // Each session start re-arms the poll with its own `$`
    stopWatching?.()
    const duty = $.clock.every(DUTY_POLL_MS, () => void recheckDuty($))
    const tick = $.clock.every(SPINNER_TICK_MS, () => {
      if (onDuty) $.ui.invalidate('ui.render')
    })
    const countdown = $.clock.every(TIMER_TICK_MS, async () => {
      if (onDuty && isCounting(await $.clock.now())) $.ui.invalidate('ui.render')
    })
    stopWatching = () => {
      duty.cancel()
      tick.cancel()
      countdown.cancel()
    }
    await loadVerbs($)
    await refreshUsage($)
    return next(e)
  })

  on('command.run', { command: 'witcher' }, async ($, e) => {
    const text = await wear($, e.args)
    await recheckDuty($)
    return { text }
  })

  on('command.run', { command: 'timer' }, async ($, e) => {
    const text = await runTimer($, e.args)
    await refreshTimer($)
    $.ui.invalidate('ui.render')
    return { text }
  })

  on('prompt.submit', async ($, e, next) => {
    const id = takeSeen()
    if (id) {
      const dir = await timerDir($)
      if (dir) await $.fs.write(`${dir}/seen`, id).catch(() => undefined)
      if (onDuty) $.ui.invalidate('ui.render')
    }
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (isExit(e.reason)) {
      // Every exit hook shares one short bound, so reap takes what is left of it
      const timeoutMs = Math.max(200, Math.floor(next.budget.remainingMs))
      await $.process.run(['bash', `${$.plugin.root}/scripts/timer.sh`, 'reap'], { timeoutMs }).catch(() => undefined)
    }
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await refreshUsage($)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    await refreshUsage($)
    return next(e)
  })

  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    // A message (compacting, a hook running) says what is happening, and on the
    // desktop the word names the step being done; both stay as they are
    if (!onDuty || e.surface !== 'terminal' || e.props.message !== null) return next(e)
    const step = await stepsSince($, e.props.word, stepMs)
    return next({ ...e, props: { ...e.props, word: ownVerb(e.props.word, verbs, step) } })
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    onDuty ??= (await isOnDuty($)) ?? true
    if (e.props.hasSurvey || !onDuty) return next(e)

    const u = await read($, usage)
    const { Box, Text } = $.ui.resolve(e)

    const wide = e.props.bodyColumns >= 110
    const w = wide ? 10 : 6
    const label = (long: string, short: string) => (wide ? long : short)

    const tox = u.ctx ?? 0
    const toxColor = tox >= threshold + TOXICITY_OVERDUE_BY ? 'error' : tox >= threshold ? 'warning' : 'success'
    // The bar reads like the game (full = good, it drains); the number reads
    // like /usage (how much is spent), tagged ctx / 5h / 7d so it cannot be
    // mistaken for what is left.
    const leftColor = (used: number) => (used >= 90 ? 'error' : used >= 70 ? 'warning' : 'success')
    const rest = timerViewAt(await $.clock.now())

    return (
      <Box flexDirection="column" marginTop={1}>
        <Box flexDirection="row">
          <Text>
            <Text color={toxColor}>☠ </Text>
            <Text dimColor>{label('Токсичність ', '')}</Text>
            <Text color={toxColor}>{toxicityBar(tox, threshold, w)}</Text>
            <Text dimColor> ctx </Text>
            <Text color={toxColor}>{tox}%</Text>
            <Text dimColor>   </Text>
          </Text>
          {u.fiveHour !== null ? (
            <Text>
              <Text color="warning">⚡ </Text>
              <Text dimColor>{label('Витривалість ', '')}</Text>
              <Text color={leftColor(u.fiveHour)}>{bar(100 - u.fiveHour, w)}</Text>
              <Text dimColor> 5h </Text>
              <Text color={leftColor(u.fiveHour)}>{u.fiveHour}%</Text>
              <Text dimColor>{u.fiveHourReset ? ` ↻ ${hhmm(u.fiveHourReset)}` : ''}</Text>
              <Text dimColor>   </Text>
            </Text>
          ) : null}
          {u.sevenDay !== null ? (
            <Text>
              <Text color="error">♥ </Text>
              <Text dimColor>{label('Вітальність ', '')}</Text>
              <Text color={leftColor(u.sevenDay)}>{bar(100 - u.sevenDay, w)}</Text>
              <Text dimColor> 7d </Text>
              <Text color={leftColor(u.sevenDay)}>{u.sevenDay}%</Text>
            </Text>
          ) : null}
          {rest.kind === 'counting' ? (
            <Text>
              <Text dimColor>   </Text>
              <Text color="claude">☾ </Text>
              <Text dimColor>{label('Медитація через ', '')}</Text>
              <Text color="claude">{formatLeft(rest.leftMs)}</Text>
            </Text>
          ) : rest.kind === 'rang' ? (
            <Text>
              <Text dimColor>   </Text>
              <Text color="claude" bold>☾ Час медитації</Text>
            </Text>
          ) : null}
        </Box>
      </Box>
    )
  })
}

files.hooks/timer.ts:
// The /timer break reminder as the HUD sees it. scripts/timer.sh owns the timer
// itself (systemd counts the time and rings), so every session, whichever
// plugin set it, reads the same files under persona-timer/. The engine does not
// let `$` cross an import, so this file holds the state and the rules and each
// register.tsx does the reading and writing.

export type TimerView = { kind: 'none' } | { kind: 'counting'; leftMs: number } | { kind: 'rang' }

let timer: { id: string; endsAt: number } | null = null
let rang: { id: string } | null = null
let seen: string | null = null

function parse(text: string | null): Record<string, unknown> | null {
  if (!text) return null
  try {
    return JSON.parse(text) as Record<string, unknown>
  } catch {
    return null
  }
}

// Takes what the three state files hold now (null when missing) and says
// whether what the band shows has changed
export function applyTimerFiles(timerText: string | null, rangText: string | null, seenText: string | null): boolean {
  const t = parse(timerText)
  const r = parse(rangText)
  const nextTimer = t && typeof t.endsAt === 'number' ? { id: String(t.id), endsAt: t.endsAt } : null
  const nextRang = r ? { id: String(r.id) } : null
  const nextSeen = seenText?.trim() || null
  const changed = nextTimer?.id !== timer?.id || nextRang?.id !== rang?.id || nextSeen !== seen
  timer = nextTimer
  rang = nextRang
  seen = nextSeen
  return changed
}

// The ring clears timer.json within seconds of the end; one still there long
// after is a timer lost to a reboot or a killed session, not one about to ring
const STALE_AFTER_MS = 60_000

export function isCounting(now: number): boolean {
  return timer !== null && now - timer.endsAt < STALE_AFTER_MS
}

export function timerViewAt(now: number): TimerView {
  if (timer && now - timer.endsAt < STALE_AFTER_MS) return { kind: 'counting', leftMs: Math.max(0, timer.endsAt - now) }
  if (rang && rang.id !== seen) return { kind: 'rang' }
  return { kind: 'none' }
}

// A prompt means the person is back: the reminder has done its job, in every
// session at once. Returns the id to record as seen, or null when nothing rang.
export function takeSeen(): string | null {
  if (!rang || rang.id === seen) return null
  seen = rang.id
  return seen
}

export function formatLeft(ms: number): string {
  const total = Math.ceil(ms / 1000)
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const ss = String(total % 60).padStart(2, '0')
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`
}

export function timerArgs(args: string): string[] {
  const arg = args.trim()
  return arg === '' ? ['status'] : arg.toLowerCase() === 'off' ? ['off'] : ['set', arg]
}

// A /clear or a resume goes on in the same process, so only a real exit counts
export function isExit(reason: string): boolean {
  return reason === 'prompt_input_exit' || reason === 'logout' || reason === 'other'
}

export const TIMER_COMMAND = {
  name: 'timer',
  description: 'Remind me to take a break: /timer 45m or 1h; no argument shows the timer, off cancels it',
  argumentHint: '[45m | 1h | off]',
}

